function parseMaybeJson(value, fallback = {}) {
  if (value && typeof value === "object") return value;

  if (typeof value !== "string") return fallback;

  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

return [{
  ...$json,

  execution_context: parseMaybeJson($json.execution_context, $json.execution_context || {}),
  context_packet: parseMaybeJson($json.context_packet, $json.context_packet || {}),
  decision: parseMaybeJson($json.decision, $json.decision || {}),
  state_update: parseMaybeJson($json.state_update, $json.state_update || {}),
  execution_meta: parseMaybeJson($json.execution_meta, $json.execution_meta || {}),

  lead_id: $json.lead_id || null,
  channel: $json.channel || "whatsapp",
  phone: $json.phone || null,

  calendar_id: $json.calendar_id || null,
  service_interest: $json.service_interest || null,
  vehicle_type: $json.vehicle_type || null,
  district: $json.district || null,

  booking_date: $json.booking_date || null,
  booking_time: $json.booking_time || null,
  slot_id: $json.slot_id || null,

  service_address: $json.service_address || null,
  address_reference: $json.address_reference || null,
  eta_minutes: $json.eta_minutes || null
}];

const data = $json;
const ctx = data.execution_context || {};
const state = data.context_packet?.state || {};

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      return value;
    }
  }
  return null;
}

const leadId = firstValue(data.lead_id, ctx.lead_id, data.context_packet?.lead?.id);
const phone = firstValue(data.phone, ctx.phone, data.context_packet?.lead?.phone);
const channel = firstValue(data.channel, ctx.channel, data.context_packet?.lead?.channel, "whatsapp");

const etaMinutes = firstValue(
  data.eta_minutes,
  ctx.eta_minutes,
  data.decision?.eta_minutes
);

const business = data.context_packet?.business || {};
const requiresPricingContext = business.pricing_policy?.requires_service_vehicle_district !== false;

let message = requiresPricingContext
  ? "Hola, voy en camino al servicio. Te aviso apenas esta llegando."
  : "Hola, te recordamos que tu hora es pronto. Te esperamos en nuestro local.";

if (etaMinutes) {
  message = requiresPricingContext
    ? `Hola, voy en camino al servicio. Llego aproximadamente en ${etaMinutes} minutos. Te aviso apenas esta llegando.`
    : `Hola, te recordamos que tu hora es en aproximadamente ${etaMinutes} minutos. Te esperamos en nuestro local.`;
}

return [{
  ...data,

  lead_id: leadId,
  phone,
  channel,

  message_to_send: message,

  db_operations: ["messages", "lead_state"],

  state_update: {
    ...(data.state_update || {}),
    stage: state.stage || "booked",
    next_goal: "complete_service",
    last_bot_action: "notify_on_the_way",
    missing_fields: []
  },

  execution_result: {
    success: true,
    action: "notify_on_the_way",
    message_sent: false,
    state_updated: true,
    db_records_created: ["messages", "lead_state"],
    notes: [
      "notify_on_the_way_message_prepared"
    ]
  },

  notes: [
    ...(data.notes || []),
    "notify_on_the_way_subworkflow_completed"
  ]
}];

